content.text:
{
  "name": "NI数字输出设备",
  "name_en": "NI Digital Output Device",
  "manufacturer": "National Instruments",
  "description": "这是一类美国国家仪器的数字输出数据采集设备，用于输出开关量或TTL电平信号，在实验中常用于触发其他仪器、控制继电器或快门、切换外部电路状态，以及实现时序同步控制。",
  "description_en": "This is a National Instruments digital output data acquisition device used to generate digital or TTL-level signals. In laboratory setups, it is commonly used to trigger other instruments, control relays or shutters, switch external circuit states, and provide timing synchronization.",
  "actions": [
    {
      "action_name": "auto-Task",
      "description": "创建或初始化数字输出任务。",
      "description_en": "Create or initialize the digital output task."
    },
    {
      "action_name": "auto-write",
      "description": "向数字输出通道写入指定的数字电平或开关值。",
      "description_en": "Write the specified digital level or switching value to the digital output channel."
    },
    {
      "action_name": "auto-stop_task",
      "description": "停止当前数字输出任务。",
      "description_en": "Stop the current digital output task."
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备连接并释放任务相关资源。",
      "description_en": "Close the device connection and release task-related resources."
    }
  ],
  "tag_hints": [
    "digital output",
    "NI-DAQ",
    "TTL triggering",
    "instrument synchronization",
    "relay control",
    "shutter control",
    "data acquisition"
  ]
}

